import { PlaneGeometry, Mesh, Group, Color, Vector2, DoubleSide } from 'three/webgpu';
import { uv, vec3, vec2, vec4, float, mix, smoothstep, abs, length, max, sub, pow, step, fract, time } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'hub-pricing-badge';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const ink = new THREE.Color(colors.ink);
  const paper = new THREE.Color(colors.paper);
  const accent = new THREE.Color(colors.accent);
  const surface = new THREE.Color(colors.surface);

  // Plane geometry sized as capsule (1.0 x 0.32 scene units)
  const W = 1.0, H = 0.32;
  const geo = new PlaneGeometry(W, H, 64, 24);

  // Smooth ceramic-grain texture
  let grainTex = null;
  ctx.textureLoader.loadTexture('/prism-assets/chrome/ceramic-grain.map.png')
    .then((t) => { t.colorSpace = THREE.SRGBColorSpace; grainTex = t; mat.needsUpdate = true; });

  // TSL uniforms
  const uHover = uniform(0);
  const uFocus = uniform(0);
  const uAccent = uniform(new THREE.Color(colors.accent));
  const uSurface = uniform(new THREE.Color(colors.surface));
  const uPaper = uniform(new THREE.Color(colors.paper));
  const uInk = uniform(new THREE.Color(colors.ink));
  const uGrain = uniform(null);

  // SDF capsule inside unit plane — uses uv in [0,1]; aspect-corrected
  const aspect = float(W / H);
  const p = sub(uv, vec2(0.5)).mul(vec2(aspect, 1.0)).mul(2.0); // now in roughly [-aspect, aspect] x [-1,1]
  // half-size and radius
  const half = vec2(aspect - 0.35, 1.0 - 0.35); // capsule: rounded ends
  const r = float(0.35);
  // standard rounded-box SDF
  const q = abs(p).sub(half);
  const qx = max(q.x, float(0.0));
  const qy = max(q.y, float(0.0));
  const outer = length(vec2(qx, qy)).add(min(max(q.x, q.y), float(0.0))).sub(r);

  // Edge softness
  const edge = smoothstep(float(0.02), float(-0.02), outer);          // 1 inside, 0 outside
  const rim = smoothstep(float(-0.08), float(0.0), outer)
    .mul(smoothstep(float(0.04), float(0.0), outer));                 // thin rim band
  const accentRim = smoothstep(float(-0.035), float(0.0), outer)
    .mul(smoothstep(float(0.018), float(-0.005), outer));             // tight accent edge

  // Surface body slightly lifted from black stage
  const bodyColor = mix(mix(uSurface, uInk, float(0.5)), uPaper.mul(float(0.18)), float(0.0));
  // accent edge light pulsing subtly
  const pulse = sin(time.mul(float(1.5))).mul(float(0.15)).add(float(0.85));
  const accentEdge = uAccent.mul(pulse);

  // Hover lift increases edge brightness + warm surface tint
  const focusRim = mix(accentEdge.mul(float(0.55)), accentEdge, uHover);
  const core = mix(bodyColor, mix(bodyColor, uAccent, float(0.06)), uHover);

  // Grain modulation
  const g = uGrain;
  const grainAmt = float(0.04);
  const grainMod = g ? g.mul(float(1.0)).r.sub(float(0.5)).mul(grainAmt) : float(0.0);

  // Alpha fade outside capsule
  const alpha = edge;

  // Compose final color
  const comp = mix(core.add(grainMod), focusRim, accentRim.mul(float(1.25)));
  const finalColor = mix(core.add(grainMod), comp, edge);
  // Apply rim near edge (rim inside body)
  const edged = mix(finalColor, focusRim, rim.mul(float(0.75)).mul(uHover.mul(float(0.7)).add(float(0.3))));

  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: true
  });
  mat.colorNode = edged;
  mat.opacityNode = alpha;

  const mesh = new Mesh(geo, mat);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // Subtle contact shadow under badge (depth anchor) — a radial dark quad on z=-0.05
  const shadowGeo = new PlaneGeometry(W * 1.15, H * 1.5, 16, 16);
  const sP = sub(uv, vec2(0.5)).mul(2.0);
  const sAlpha = smoothstep(float(1.0), float(0.0), length(sP)).mul(float(0.45));
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, toneMapped: true });
  shadowMat.colorNode = vec4(vec3(0.0), sAlpha);
  shadowMat.opacityNode = sAlpha;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = -0.05;
  mesh.add(shadow);

  // Initial state for entrance settle
  group.position.set(0, 0, 0);
  group.scale.set(0.96, 0.96, 0.96);
  mesh.position.y = 0.18;

  // GSAP entrance: weighted-settle on scale, rise-in on y
  const tl = gsap.timeline();
  tl.to(mesh.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  tl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55,
    ease: 'power2.out'
  }, 0).to(group.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.45,
    ease: 'power4.out'
  }, 0.5);

  // Event handlers (hover + click) — attach to userData.handlers
  let hoverAnim = null;
  group.userData.handlers = {
    pointerenter: () => {
      uHover.value = 1.0;
      hoverAnim && hoverAnim.kill();
      hoverAnim = gsap.to(mesh.position, {
        y: 0.05,
        duration: 0.5,
        ease: 'power3.out'
      });
    },
    pointerleave: () => {
      uHover.value = 0.0;
      hoverAnim && hoverAnim.kill();
      hoverAnim = gsap.to(mesh.position, {
        y: 0,
        duration: 0.4,
        ease: 'power2.out'
      });
    },
    click: () => {
      // press-down
      gsap.to(group.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1.0, y: 1.0, z: 1.0,
            duration: 0.4,
            ease: 'power4.out'
          });
          ctx.emit('hub-pricing.select', { source: 'hub-pricing-badge' });
        }
      });
    }
  };

  // Cleanup
  const cleanups = [];
  group.userData.cleanup = () => {
    tl.kill();
    hoverAnim && hoverAnim.kill();
    geo.dispose();
    shadowGeo.dispose();
    mat.dispose();
    shadowMat.dispose();
    if (grainTex) grainTex.dispose && grainTex.dispose();
    cleanups.forEach(c => { try { c(); } catch (e) {} });
  };

  return group;
}
